package com.flashlearn.domain.backup

import com.flashlearn.domain.model.*
import java.time.Instant
import java.util.UUID

enum class BackupType { VOCABULARY, PROGRESS, FULL }
data class BackupData(val schemaVersion:Int,val exportedAt:Instant,val backupType:BackupType,val languages:List<BackupLanguage> = emptyList(),val categories:List<Category> = emptyList(),val tags:List<BackupTag> = emptyList(),val languagePairs:List<BackupLanguagePair> = emptyList(),val concepts:List<Concept> = emptyList(),val contents:List<Content> = emptyList(),val settings:Map<String,String> = emptyMap(),val reviewSessions:List<ReviewSession> = emptyList(),val reviewHistory:List<ReviewHistory> = emptyList(),val learningStates:List<LearningState> = emptyList(),val difficultyStates:List<DifficultyState> = emptyList(),val parserMetadata:List<BackupParserMetadata> = emptyList(),val achievements:List<BackupAchievement> = emptyList(),val relations:List<VocabularyRelation> = emptyList(),val variants:List<VocabularyVariant> = emptyList(),val reviewQueue:List<ReviewQueueItem> = emptyList(),val conceptReferences:Set<UUID> = emptySet())
data class BackupLanguage(val id:UUID,val code:String,val name:String)
data class BackupTag(val id:UUID,val name:String)
data class BackupLanguagePair(val id:UUID,val sourceLanguageId:UUID,val targetLanguageId:UUID)
data class BackupAchievement(val id:UUID,val key:String,val unlockedAt:Instant?)
data class BackupParserMetadata(val conceptId:UUID,val breakdownJson:String,val relationshipsJson:String,val variantsJson:String,val confidence:Double)
data class BackupValidationIssue(val code:String,val message:String)
data class BackupValidationResult(val valid:Boolean,val issues:List<BackupValidationIssue>)
object BackupValidator{
 fun validate(data:BackupData,supportedSchemaVersion:Int):BackupValidationResult{val issues=mutableListOf<BackupValidationIssue>();if(data.schemaVersion !in 1..supportedSchemaVersion)issues+=BackupValidationIssue("UNSUPPORTED_SCHEMA","Unsupported schemaVersion=${data.schemaVersion}");fun<T>dups(items:List<T>,id:(T)->UUID,label:String){val d=items.groupingBy(id).eachCount().filterValues{it>1}.keys;if(d.isNotEmpty())issues+=BackupValidationIssue("DUPLICATE_UUID","$label contains duplicate UUIDs: $d")};dups(data.languages,{it.id},"languages");dups(data.categories,{it.id},"categories");dups(data.tags,{it.id},"tags");dups(data.languagePairs,{it.id},"languagePairs");dups(data.concepts,{it.id},"concepts");dups(data.contents,{it.id},"contents");dups(data.learningStates,{it.id},"learningStates");dups(data.difficultyStates,{it.id},"difficultyStates");dups(data.reviewSessions,{it.id},"reviewSessions");dups(data.reviewHistory,{it.id},"reviewHistory");dups(data.achievements,{it.id},"achievements");dups(data.relations,{it.id},"relations");dups(data.variants,{it.id},"variants");dups(data.reviewQueue,{it.id},"reviewQueue");val ids=data.concepts.map{it.id}.toSet();val cat=data.categories.map{it.id}.toSet();val sessions=data.reviewSessions.associateBy{it.id};data.concepts.forEach{if(it.categoryId!=null&&it.categoryId !in cat)issues+=BackupValidationIssue("BROKEN_REFERENCE","Concept ${it.id} references Category ${it.categoryId}")};data.contents.forEach{if(it.conceptId !in ids)issues+=BackupValidationIssue("BROKEN_REFERENCE","Content ${it.id} references Concept ${it.conceptId}")};data.learningStates.forEach{if(it.conceptId !in ids)issues+=BackupValidationIssue("BROKEN_REFERENCE","LearningState ${it.id} references Concept ${it.conceptId}")};data.difficultyStates.forEach{if(it.conceptId !in ids)issues+=BackupValidationIssue("BROKEN_REFERENCE","DifficultyState ${it.id} references Concept ${it.conceptId}")};data.relations.forEach{if(it.sourceConceptId !in ids)issues+=BackupValidationIssue("BROKEN_REFERENCE","Relation ${it.id} source is missing");if(it.targetConceptId!=null&&it.targetConceptId !in ids)issues+=BackupValidationIssue("BROKEN_REFERENCE","Relation ${it.id} target is missing")};data.variants.forEach{if(it.conceptId !in ids)issues+=BackupValidationIssue("BROKEN_REFERENCE","Variant ${it.id} references Concept ${it.conceptId}")};data.reviewQueue.forEach{if(it.conceptId!=null&&it.conceptId !in ids)issues+=BackupValidationIssue("BROKEN_REFERENCE","ReviewQueue ${it.id} references Concept ${it.conceptId}")};data.parserMetadata.forEach{if(it.conceptId !in ids)issues+=BackupValidationIssue("BROKEN_REFERENCE","ParserMetadata references Concept ${it.conceptId}");if(!it.confidence.isFinite()||it.confidence !in 0.0..1.0)issues+=BackupValidationIssue("INVALID_VALUE","ParserMetadata confidence=${it.confidence}")};val contentKeys=data.contents.groupingBy{Triple(it.conceptId,it.languageCode,it.translationIndex)}.eachCount();if(contentKeys.values.any{it>1})issues+=BackupValidationIssue("DUPLICATE_CONTENT_INDEX","Multiple Content rows share concept/language/translationIndex");if(data.contents.any{it.translationIndex<0})issues+=BackupValidationIssue("INVALID_VALUE","translationIndex cannot be negative");val attempts=data.reviewHistory.groupingBy{it.sessionId to it.reviewAttemptId}.eachCount();if(attempts.values.any{it>1})issues+=BackupValidationIssue("DUPLICATE_REVIEW_ATTEMPT","Multiple ReviewHistory rows share sessionId/reviewAttemptId");data.reviewHistory.forEach{if(it.conceptId !in ids||it.sessionId !in sessions)issues+=BackupValidationIssue("BROKEN_REFERENCE","ReviewHistory ${it.id} has a broken reference");val s=sessions[it.sessionId];if(s!=null&&s.reviewType!=it.reviewType)issues+=BackupValidationIssue("TYPE_MISMATCH","ReviewHistory ${it.id} reviewType does not match session")};if(data.backupType==BackupType.PROGRESS&&data.concepts.isNotEmpty())issues+=BackupValidationIssue("TYPE_MISMATCH","PROGRESS backup must not contain Concepts");if(data.backupType==BackupType.VOCABULARY&&(data.learningStates.isNotEmpty()||data.difficultyStates.isNotEmpty()||data.reviewHistory.isNotEmpty()))issues+=BackupValidationIssue("TYPE_MISMATCH","VOCABULARY backup must not contain progress data");return BackupValidationResult(issues.isEmpty(),issues)}
}
